PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL, last_served INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE api_tokens(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, hits INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE bots(id TEXT PRIMARY KEY, owner_id TEXT REFERENCES users(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', builtin INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX bots_owner_name ON bots(owner_id,name);
CREATE TABLE versions(id TEXT PRIMARY KEY, bot_id TEXT NOT NULL REFERENCES bots(id), version TEXT NOT NULL, object_key TEXT, sha256 TEXT NOT NULL, filename TEXT NOT NULL, size INTEGER NOT NULL, notes TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, UNIQUE(bot_id,version));
CREATE TABLE jobs(id TEXT PRIMARY KEY, owner_id TEXT REFERENCES users(id), name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'private', candidate_id TEXT REFERENCES versions(id), config_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_ranked_job ON jobs(candidate_id) WHERE kind='ranked';
CREATE TABLE matches(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), owner_id TEXT REFERENCES users(id), mode INTEGER NOT NULL, seed INTEGER NOT NULL, seat_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, lease_token TEXT, lease_until INTEGER, error TEXT, replay_key TEXT, result_json TEXT, public INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, started_at INTEGER, finished_at INTEGER);
CREATE INDEX match_claim ON matches(status,lease_until,created_at);
CREATE INDEX match_owner ON matches(owner_id,created_at);
CREATE INDEX match_job ON matches(job_id,status);
CREATE TABLE attempts(match_id TEXT NOT NULL REFERENCES matches(id), number INTEGER NOT NULL, status TEXT NOT NULL, error TEXT, log_key TEXT, created_at INTEGER NOT NULL, finished_at INTEGER, PRIMARY KEY(match_id,number));
CREATE TABLE runners(id TEXT PRIMARY KEY, last_seen INTEGER NOT NULL, version TEXT NOT NULL);
